// logger, usage: log(this, "");
const log = global.get('logger');

// Stop when the outside temperature is unavailable
if (!isFinite(msg.feedforward.outside_temp)) {
    log(this, "Outside temperature unavailable", "warn");
    node.status({ fill: "red", shape: "ring", text: "No outside temperature" });
    return null;
}

node.status({});
return msg;

// Cache the hourly forecast as [{ t: ms, temp: °C }], read by 'Get forecast'
const response = msg.payload || {};
const forecast = Object.values(response)[0]?.forecast || [];

flow.set("weather_forecast", {
    fetched: Date.now(),
    list: forecast.map(f => ({ t: new Date(f.datetime).getTime(), temp: f.temperature })),
});
return msg;

// Only use a forecast with data, fetched in the last 3 hours
const forecast = msg.forecast;
return (forecast && forecast.list && forecast.list.length > 0 &&
    Date.now() - forecast.fetched < 3 * 3_600_000) ? [msg, null] : [null, msg];

// Forecast temperatures from the cached hourly forecast
const ff = msg.feedforward;
const list = msg.forecast.list; // [{ t: ms, temp: °C }]
const HOUR_MS = 3_600_000;
const now = Date.now();

// Temperature at time t, linear between the hourly forecast points
function at(t) {
    if (t <= list[0].t) return list[0].temp;
    for (let i = 1; i < list.length; i++) {
        if (t <= list[i].t) {
            const a = list[i - 1], b = list[i];
            return a.temp + (b.temp - a.temp) * (t - a.t) / (b.t - a.t);
        }
    }
    return list[list.length - 1].temp;
}

// Average temperature over [from, from + hours], sampled every 15 minutes
function average(from, hours) {
    if (!(hours > 0)) return at(from);
    const steps = Math.round(hours * 4);
    let sum = 0;
    for (let i = 0; i < steps; i++) sum += at(from + (i + 0.5) * hours * HOUR_MS / steps);
    return sum / steps;
}

ff.forecast_now = at(now);                                                            // bias correction
ff.forecast_temp = average(now + ff.forecast_lead_time * HOUR_MS, ff.forecast_window); // heating curve
ff.forecast_avg = average(now, ff.simple_forecast_hours);                             // simple schedule

return msg;

// Difference between the measured and the forecast temperature right now
const ff = msg.feedforward;
ff.forecast_bias = ff.outside_temp - ff.forecast_now;
return msg;

const ff = msg.feedforward;

// Forecast, shifted by the bias (0 without bias correction)
ff.forecast_temp = ff.forecast_temp + ff.forecast_bias;

// Heating curve: mix of the current and the forecast temperature, weight in %
ff.outside_temp_used = ff.outside_temp + ff.forecast_weight / 100 * (ff.forecast_temp - ff.outside_temp);

// Simple day schedule: average forecast over the next hours
ff.outside_temp_avg_used = Math.round((ff.forecast_avg + ff.forecast_bias) * 10) / 10;

delete msg.forecast;
return msg;

// The history curve exists once the Heat Pump History flow has run
const fit = global.get("heat_pump_history")?.fit?.water_target_temp;
return (fit && fit.slope !== undefined) ? [msg, null] : [null, msg];

// Straight line from the Heat Pump History flow: water = slope * outside + intercept
const ff = msg.feedforward;
const fit = global.get("heat_pump_history").fit.water_target_temp;

ff.slope = fit.slope;
ff.intercept = fit.intercept;
ff.water_curve = ff.slope * ff.outside_temp_used + ff.intercept;
return msg;

// Water temperature per outside temperature, from input_number.feedforward_home_*
const ff = msg.feedforward;

ff.table = [
    { outside: -20, water: ff.table_min20 },
    { outside: -10, water: ff.table_min10 },
    { outside: 0, water: ff.table_0 },
    { outside: 10, water: ff.table_plus10 },
    { outside: 20, water: ff.table_plus20 },
];
return msg;

// Linear between the two surrounding points, the end value beyond the table
const ff = msg.feedforward;
const table = ff.table; // sorted from cold to warm
const x = ff.outside_temp_used;
const first = table[0];
const last = table[table.length - 1];

if (x <= first.outside) {
    ff.water_curve = first.water;
} else if (x >= last.outside) {
    ff.water_curve = last.water;
} else {
    const i = table.findIndex(p => p.outside > x); // first point above x
    const below = table[i - 1];
    const above = table[i];
    ff.water_curve = below.water + (above.water - below.water) * (x - below.outside) / (above.outside - below.outside);
}
return msg;

const ff = msg.feedforward;
ff.mode = "Curve";
ff.heating = true;

// Heating curve, limited to the min / max water temperature
ff.water_temp = Math.min(Math.max(ff.water_curve, ff.min_water_temp), ff.max_water_temp);
return msg;

// The heating day starts at the start time, before that time the previous day still counts
const [h, m] = String(msg.feedforward.simple_start_time || "00:00").split(":").map(Number);
const start = new Date();
start.setHours(h || 0, m || 0, 0, 0);
if (Date.now() < start.getTime()) start.setDate(start.getDate() - 1);

msg.feedforward.heating_day = start.toISOString();
return msg;

const ff = msg.feedforward;
const round = (v, digits) => (v === undefined || !isFinite(v)) ? undefined : Number(v.toFixed(digits));

ff.water_temp = round(ff.water_temp, 1);
ff.outside_temp_used = round(ff.outside_temp_used, 1);
ff.forecast_temp = round(ff.forecast_temp, 1);
ff.forecast_bias = round(ff.forecast_bias, 1);

// Expected power and COP at this outside temperature, from the Heat Pump History flow
const fit = global.get("heat_pump_history")?.fit || {};
const atOutside = (line) => line ? line.slope * ff.outside_temp_used + line.intercept : undefined;
ff.expected_power = round(atOutside(fit.power), 0);
ff.expected_cop = round(atOutside(fit.cop), 2);

global.set("heat_pump_feedforward", { ...ff });
return msg;

// Status
const ff = msg.feedforward;
const text = ff.heating ? `${ff.water_temp} °C` : "Off for today";
node.status({ fill: ff.heating ? "green" : "grey", shape: "dot", text: `${text} @ ${ff.outside_temp_used} °C (${ff.mode}, ${ff.source}, ${ff.outside_source})` });

return msg;

// Log unhandled exception
const handle = global.get('unhandledException');
if(handle) handle(this);

return msg;
